<script lang="ts">
  import {onMount} from 'svelte';
  import {api,websocketUrl} from '../lib/api.js';
  import {chooseContext,type WorkbenchState} from '../lib/workbench-state.js';
  import {contextActions} from '../lib/context-actions.js';
  import {loadContextCatalog} from '../lib/context-catalog.js';
  import Search from '@lucide/svelte/icons/search';import SquareTerminal from '@lucide/svelte/icons/square-terminal';import ScanSearch from '@lucide/svelte/icons/scan-search';import Map from '@lucide/svelte/icons/map';import MoreHorizontal from '@lucide/svelte/icons/more-horizontal';import FolderOpen from '@lucide/svelte/icons/folder-open';import Network from '@lucide/svelte/icons/network';import Activity from '@lucide/svelte/icons/activity';import Database from '@lucide/svelte/icons/database';import RadioTower from '@lucide/svelte/icons/radio-tower';
  export let state:WorkbenchState;
  let contexts:any[]=[];let selected='local';let current:any;let status='Discovering FNGK…';let repository='/workspace';let overflow='';let query='';let results:any[]=[];let searching=false;let timer:any;let searchController:AbortController|undefined;let searchGeneration=0;const sockets=new Set<WebSocket>();
  const label=(item:any)=>`${item.name}${item.device?.agentMode?` · ${item.device.agentMode}`:''}${item.device?.id?` · ${item.device.id.slice(0,8)}`:''}`;
  async function refreshWorld(message:string){status=message;try{await api('/api/world/refresh',{method:'POST',body:JSON.stringify({contextId:selected})});window.dispatchEvent(new Event('atlas:graph-refresh'));status=message.replace(/…$/,' complete')}catch(error){status=(error as Error).message}}
  async function load(force=false){if(force)state.setConnection({phase:'checking',message:'Refreshing FNGK namespace…'});try{const value=await loadContextCatalog(force);contexts=value.contexts;selected=chooseContext(contexts,state.snapshot());state.setContext(selected,false);const local=contexts.find((item:any)=>item.id==='local');if(local?.workspaceRoot)repository=local.workspaceRoot;if(value.state.compatible){status=`${value.state.profile??'default'} · ${value.state.version}`;state.setConnection({phase:'connected',message:`Connected to ${value.state.profile??'default'}`,profile:value.state.profile,version:value.state.version});}else{status=value.state.reason??'FNGK unavailable';state.setConnection({phase:value.state.login==='required'?'authentication-required':'unavailable',message:status,profile:value.state.profile,version:value.state.version});}}catch(error){status=(error as Error).message;contexts=[{id:'local',name:'Atlas process host',kind:'local',online:true}];selected='local';state.setContext('local',false);state.setConnection({phase:'unavailable',message:status});}}
  function scan(){const socket=new WebSocket(websocketUrl(`/api/discovery/scan?contextId=${encodeURIComponent(selected)}`));let failed=false;sockets.add(socket);status='Scanning host…';socket.onmessage=e=>{const v=JSON.parse(e.data);if(v.type==='error'){failed=true;status=v.message??v.code;}state.appendActivity(`${v.type} · ${v.scanned??''}`)};socket.onclose=()=>{sockets.delete(socket);if(!failed)void refreshWorld('Interpreting scan evidence…')}}
  function analyze(){if(!repository.trim())return;const socket=new WebSocket(websocketUrl(`/api/analysis/repository?contextId=${encodeURIComponent(selected)}&path=${encodeURIComponent(repository)}`));let completed=false,failed=false;sockets.add(socket);status='Mapping repository…';socket.onmessage=e=>{const v=JSON.parse(e.data);if(v.type==='error'){failed=true;status=v.message??v.code}state.appendActivity(`${v.type} · ${v.index?.summary?.functions??v.nodes?.length??''}`);if(v.type==='analysis_complete'){completed=true;void refreshWorld('Interpreting repository evidence…')}};socket.onclose=()=>{sockets.delete(socket);if(!completed&&!failed)status='Analysis stopped'}}
  function action(name:string){overflow='';const registered=contextActions.find(item=>item.id===name);if(registered){registered.run({...state.snapshot(),contextId:selected,selection:{id:repository,type:'repository',path:repository}});return}if(name==='scan')scan();if(name==='map')analyze();}
  function search(){clearTimeout(timer);searchController?.abort();const value=query.trim(),generation=++searchGeneration;results=[];if(!value){searching=false;return}searching=true;timer=setTimeout(async()=>{const controller=new AbortController();searchController=controller;try{const response=await api<any>(`/api/search?contextId=${encodeURIComponent(selected)}&q=${encodeURIComponent(value)}&limit=80`,{signal:controller.signal});if(generation!==searchGeneration||controller.signal.aborted)return;results=(response.items??[]).slice(0,80)}catch(error){if(generation===searchGeneration&&!controller.signal.aborted)results=[]}finally{if(generation===searchGeneration)searching=false}},160)}
  function openResult(item:any){const resultContext=item.contextId??selected;if(resultContext!==selected)return;if(item.entityId&&(item.namespace||item.workloadId||String(item.entityId).startsWith('world:'))){window.dispatchEvent(new CustomEvent('atlas:navigate',{detail:{rootId:item.entityId,view:item.kind==='function'||item.kind==='module'?'software':'overview'}}));state.select({id:item.entityId,type:item.kind??item.type,contextId:resultContext,label:item.label,semantic:true});return}if(item.path&&['file','module','function','test'].includes(item.type)){const root=item.repositoryRoot??repository,path=item.path.startsWith('/')?item.path:`${root}/${item.path}`.replaceAll('//','/');window.dispatchEvent(new CustomEvent('atlas:open-file',{detail:{contextId:resultContext,path,pinned:true,semanticOrigin:{workloadId:item.workloadId,entityId:item.entityId}}}));return}state.select({id:item.entityId,type:item.type,path:item.path});window.dispatchEvent(new Event('atlas:graph-refresh'))}
  $: current=contexts.find(item=>item.id===selected);
  onMount(()=>{void load();const stateUnsub=state.subscribe(value=>{if(value.contextId===selected)return;searchController?.abort();searchGeneration++;selected=value.contextId;overflow='';results=[];query='';}),runScan=()=>scan(),runAnalyze=()=>analyze();window.addEventListener('atlas:scan',runScan);window.addEventListener('atlas:analyze',runAnalyze);return()=>{stateUnsub();searchController?.abort();clearTimeout(timer);for(const socket of sockets)socket.close();window.removeEventListener('atlas:scan',runScan);window.removeEventListener('atlas:analyze',runAnalyze)}});
</script>

<aside class="navigator context-navigator"><section class="context-sidebar">
    <header><div><strong>{current?.name??'Context'}</strong><small>{current?label(current):selected}</small></div><div><button title="Browse filesystem" onclick={()=>action('files')}><FolderOpen size={14}/></button>{#if current?.kind==='fngk-device'}<button title="Open terminal" onclick={()=>action('terminal')}><SquareTerminal size={14}/></button>{/if}<button title="More actions" onclick={()=>overflow=overflow?'':selected}><MoreHorizontal size={15}/></button></div></header>
    {#if overflow}<div class="context-popover"><button onclick={()=>action('architecture')}><Network size={13}/>Architecture</button><button onclick={()=>action('scan')}><ScanSearch size={13}/>Scan host</button><button onclick={()=>action('map')}><Map size={13}/>Map repository</button><button onclick={()=>action('database')}><Database size={13}/>Databases</button>{#if current?.kind==='fngk-device'}<button onclick={()=>action('live')}><RadioTower size={13}/>Dev run</button><button onclick={()=>action('deploy')}><RadioTower size={13}/>Deployment workbench</button>{/if}<button onclick={()=>window.dispatchEvent(new Event('atlas:focus-metrics'))}><Activity size={13}/>Evidence</button></div>{/if}
    <div class="context-search"><Search size={14}/><input bind:value={query} oninput={search} placeholder="Search functions, modules, processes…" aria-label="Search selected context"/>{#if searching}<span>…</span>{/if}</div>
    <div class="search-results">{#each results as item}<button onclick={()=>openResult(item)}><span>{item.kind??item.type}</span><b>{item.label}</b><small>{item.workloadLabel?`${item.workloadLabel} · `:''}{item.path||item.detail}</small><em>{item.contextId??selected} · {item.namespace??item.source??'index'}</em></button>{/each}{#if query&&!searching&&!results.length}<p>No indexed matches in this context. Partial search failures are ignored.</p>{/if}</div>
    <div class="repository-config"><label for="repository-path">Repository path</label><div><input id="repository-path" bind:value={repository} aria-label="Repository path"/><button title="Map repository" onclick={analyze}><Map size={14}/></button></div></div>
    <footer>{status}</footer>
  </section></aside>
